/**
 * A change to an item, and the version it was read at.
 *
 * A type or a tier the item already has moves nothing and is not sent. A
 * `type` the copy's catalog does not hold is refused `UnknownType` before
 * anything is queued.
 */
public struct Edit: Equatable, Hashable {
    /**
     * Whole field values; a device never merges inside a field. Unless
     * `replace_properties` is set, each property given replaces its value and
     * the rest stay, and a `null` clears nothing: the server drops it, and
     * so does the copy, so the property keeps its value. To remove a
     * property, name it in `clear_properties`.
     */
    public var properties: JsonObject
    /**
     * The properties are the item's whole properties: one left out is
     * cleared. Sent at a version older than the one the copy holds, through
     * `update_item_as_read`, it is merged as a merge is.
     */
    public var replaceProperties: Bool
    /**
     * Properties to remove from the item. Every other property stays as the
     * row holds it, one the app cannot read included, so a removal needs no
     * `replace_properties`. A name the item lacks is not an error; one also
     * in `properties`, or a field the type requires, is refused before
     * anything is queued.
     */
    public var clearProperties: [String]
    /**
     * The version the change was made against.
     */
    public var baseVersion: Int64
    /**
     * The natural key to move the row to.
     */
    public var sourceId: String?
    /**
     * The type to move the row to, sent as the server's retype. The
     * properties it ends up with are held to that type.
     */
    public var type: String?
    /**
     * The tier to move the row to.
     */
    public var tier: Tier?
    /**
     * When the item's content happened.
     */
    public var occurredAt: String?
    /**
     * Gives the item no time of its own again, so it is its creation time.
     * Refused beside `occurred_at`.
     */
    public var clearOccurredAt: Bool
    /**
     * The server refuses the change, merging none of it, where the item has
     * moved past `base_version`: the queued write is refused with the reason
     * `version_conflict`, and the copy shows the item as the server holds
     * it. A `base_version` older than the copy holds throws `Validation`
     * with `version_conflict` and queues nothing, except `0` read behind this
     * copy's own create that the server has yet to answer: it is queued on
     * the version that create made, and the server refuses it if the item has
     * moved since.
     */
    public var exact: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Whole field values; a device never merges inside a field. Unless
         * `replace_properties` is set, each property given replaces its value and
         * the rest stay, and a `null` clears nothing: the server drops it, and
         * so does the copy, so the property keeps its value. To remove a
         * property, name it in `clear_properties`.
         */properties: JsonObject = JsonObject(), 
        /**
         * The properties are the item's whole properties: one left out is
         * cleared. Sent at a version older than the one the copy holds, through
         * `update_item_as_read`, it is merged as a merge is.
         */replaceProperties: Bool = false, 
        /**
         * Properties to remove from the item. Every other property stays as the
         * row holds it, one the app cannot read included, so a removal needs no
         * `replace_properties`. A name the item lacks is not an error; one also
         * in `properties`, or a field the type requires, is refused before
         * anything is queued.
         */clearProperties: [String] = [], 
        /**
         * The version the change was made against.
         */baseVersion: Int64, 
        /**
         * The natural key to move the row to.
         */sourceId: String? = nil, 
        /**
         * The type to move the row to, sent as the server's retype. The
         * properties it ends up with are held to that type.
         */type: String? = nil, 
        /**
         * The tier to move the row to.
         */tier: Tier? = nil, 
        /**
         * When the item's content happened.
         */occurredAt: String? = nil, 
        /**
         * Gives the item no time of its own again, so it is its creation time.
         * Refused beside `occurred_at`.
         */clearOccurredAt: Bool = false, 
        /**
         * The server refuses the change, merging none of it, where the item has
         * moved past `base_version`: the queued write is refused with the reason
         * `version_conflict`, and the copy shows the item as the server holds
         * it. A `base_version` older than the copy holds throws `Validation`
         * with `version_conflict` and queues nothing, except `0` read behind this
         * copy's own create that the server has yet to answer: it is queued on
         * the version that create made, and the server refuses it if the item has
         * moved since.
         */exact: Bool = false) {
        self.properties = properties
        self.replaceProperties = replaceProperties
        self.clearProperties = clearProperties
        self.baseVersion = baseVersion
        self.sourceId = sourceId
        self.type = type
        self.tier = tier
        self.occurredAt = occurredAt
        self.clearOccurredAt = clearOccurredAt
        self.exact = exact
    }

    

    
}

