/**
 * Why a `blocked` write has stopped.
 */

public enum BlockedReason: Equatable, Hashable, CaseIterable {
    
    case credentialRefused
    case keySpent
    case ancestorUnavailable
    case conflictUnresolved
    /**
     * The write keeps meeting an environmental failure while the server
     * answers other writes.
     */
    case failingAlone
    /**
     * The write was queued against an instance other than the one the copy
     * has been built from since, and is sent only once released.
     */
    case instanceChanged
    /**
     * The write was carried from a store set aside where a record that
     * decides how it is sent could not be read, and is sent only once
     * released.
     */
    case recordUnread
    /**
     * The device queued the write to put back what it held that a server
     * restored to an earlier point no longer holds, and it is sent only once
     * released.
     */
    case serverRestored





}

#if compiler(>=6)
extension BlockedReason: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlockedReason: FfiConverterRustBuffer {
    typealias SwiftType = BlockedReason

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BlockedReason {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .credentialRefused
        
        case 2: return .keySpent
        
        case 3: return .ancestorUnavailable
        
        case 4: return .conflictUnresolved
        
        case 5: return .failingAlone
        
        case 6: return .instanceChanged
        
        case 7: return .recordUnread
        
        case 8: return .serverRestored
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BlockedReason, into buf: inout [UInt8]) {
        switch value {
        
        
        case .credentialRefused:
            writeInt(&buf, Int32(1))
        
        
        case .keySpent:
            writeInt(&buf, Int32(2))
        
        
        case .ancestorUnavailable:
            writeInt(&buf, Int32(3))
        
        
        case .conflictUnresolved:
            writeInt(&buf, Int32(4))
        
        
        case .failingAlone:
            writeInt(&buf, Int32(5))
        
        
        case .instanceChanged:
            writeInt(&buf, Int32(6))
        
        
        case .recordUnread:
            writeInt(&buf, Int32(7))
        
        
        case .serverRestored:
            writeInt(&buf, Int32(8))
        
        }
    }
}


