// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What a held stream changed in the copy, what became of the server, or
 * what became of the queue it drained then. `cursor` is the cursor held
 * after it.
 */

public enum Change: Equatable, Hashable {
    
    /**
     * An event the stream applied, by the event's type, with the item or
     * edge it was about.
     */
    case applied(event: String, itemId: String?, edgeId: String?, cursor: String
    )
    /**
     * A stream it opened read a catalog that differs from the one held.
     */
    case catalogChanged(cursor: String
    )
    /**
     * No stream can be had, told once until one is had again. `reason` is
     * the failure, such as the network failing, a rate limit, a failing
     * server or a refusal naming no contract.
     */
    case serverUnreachable(reason: MarfaError, cursor: String
    )
    /**
     * A stream is had again. Where a drain has work queued, the follow
     * drains once and tells `QueueDrained` or `QueueNotDrained`.
     */
    case serverReachable(cursor: String
    )
    /**
     * The queue was drained once a stream was had again, and what that
     * drain did, as `drain` returns it.
     */
    case queueDrained(report: DrainReport, cursor: String
    )
    /**
     * The drain started once a stream was had again ended with `error`.
     * The answers it had recorded stay recorded.
     */
    case queueNotDrained(error: MarfaError, cursor: String
    )
    /**
     * Told by a watch of a reading handle: another process saved to the
     * store, which now has this data version.
     */
    case saved(dataVersion: Int64, cursor: String
    )
    /**
     * Told by a watch, once, when what feeds it fails. A follow that failed
     * holds no stream until the next hydration or catch-up; a reading
     * handle's reads go on, and the first that works is told as `Saved`.
     */
    case watchFailed(reason: MarfaError, cursor: String
    )
    /**
     * The follow finished filling this table or found it over the cap.
     */
    case tableFilled(itemId: String, table: String, cursor: String
    )





}

#if compiler(>=6)
extension Change: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeChange: FfiConverterRustBuffer {
    typealias SwiftType = Change

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Change {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .applied(event: try FfiConverterString.read(from: &buf), itemId: try FfiConverterOptionString.read(from: &buf), edgeId: try FfiConverterOptionString.read(from: &buf), cursor: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .catalogChanged(cursor: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .serverUnreachable(reason: try FfiConverterTypeMarfaError.read(from: &buf), cursor: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .serverReachable(cursor: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .queueDrained(report: try FfiConverterTypeDrainReport.read(from: &buf), cursor: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .queueNotDrained(error: try FfiConverterTypeMarfaError.read(from: &buf), cursor: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .saved(dataVersion: try FfiConverterInt64.read(from: &buf), cursor: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .watchFailed(reason: try FfiConverterTypeMarfaError.read(from: &buf), cursor: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .tableFilled(itemId: try FfiConverterString.read(from: &buf), table: try FfiConverterString.read(from: &buf), cursor: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Change, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .applied(event,itemId,edgeId,cursor):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(event, into: &buf)
            FfiConverterOptionString.write(itemId, into: &buf)
            FfiConverterOptionString.write(edgeId, into: &buf)
            FfiConverterString.write(cursor, into: &buf)
            
        
        case let .catalogChanged(cursor):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(cursor, into: &buf)
            
        
        case let .serverUnreachable(reason,cursor):
            writeInt(&buf, Int32(3))
            FfiConverterTypeMarfaError.write(reason, into: &buf)
            FfiConverterString.write(cursor, into: &buf)
            
        
        case let .serverReachable(cursor):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(cursor, into: &buf)
            
        
        case let .queueDrained(report,cursor):
            writeInt(&buf, Int32(5))
            FfiConverterTypeDrainReport.write(report, into: &buf)
            FfiConverterString.write(cursor, into: &buf)
            
        
        case let .queueNotDrained(error,cursor):
            writeInt(&buf, Int32(6))
            FfiConverterTypeMarfaError.write(error, into: &buf)
            FfiConverterString.write(cursor, into: &buf)
            
        
        case let .saved(dataVersion,cursor):
            writeInt(&buf, Int32(7))
            FfiConverterInt64.write(dataVersion, into: &buf)
            FfiConverterString.write(cursor, into: &buf)
            
        
        case let .watchFailed(reason,cursor):
            writeInt(&buf, Int32(8))
            FfiConverterTypeMarfaError.write(reason, into: &buf)
            FfiConverterString.write(cursor, into: &buf)
            
        
        case let .tableFilled(itemId,table,cursor):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(itemId, into: &buf)
            FfiConverterString.write(table, into: &buf)
            FfiConverterString.write(cursor, into: &buf)
            
        }
    }
}


