/**
 * Every variant carries `message`, the core's own sentence for it, because
 * UniFFI renders an error's description by reflection otherwise.
 */
public enum MarfaError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case NotFound(code: String, message: String, 
        /**
         * What a server sent, present only where one answered.
         */server: ServerAnswer?
    )
    case Unauthorized(code: String, message: String, server: ServerAnswer?
    )
    case Forbidden(code: String, message: String, server: ServerAnswer?
    )
    case Validation(code: String, message: String, 
        /**
         * The copy's own details; a server's details belong in `server`.
         */details: JsonValue?, server: ServerAnswer?
    )
    case UnknownType(message: String, server: ServerAnswer?
    )
    case RateLimited(code: String, message: String, retryAfterSeconds: UInt64?, server: ServerAnswer?
    )
    case Server(status: UInt16, code: String, message: String, details: JsonValue?, server: ServerAnswer?
    )
    case Io(message: String
    )
    case Network(message: String
    )
    /**
     * Something in front of the server answered `status` naming no
     * contract: taken as the network failing, never as the server's word.
     */
    case Unnamed(status: UInt16, message: String, server: ServerAnswer?
    )
    case Decoding(message: String
    )
    case Store(message: String
    )
    case StoreBusy(message: String
    )
    case Redirected(origin: String, status: UInt16, location: String?, message: String, server: ServerAnswer?
    )
    case StorageFull(message: String
    )
    case SignedOut(origin: String, message: String
    )
    case NoKeychain(message: String
    )
    case NoServer(message: String
    )
    case NoCursor(message: String
    )
    case HydrationIncomplete(message: String
    )
    /**
     * The copy has never held the type catalog: a hydration reads it.
     */
    case NoCatalog(message: String
    )
    /**
     * A store another build made. Carried rather than left in the message,
     * because a Swift caller showing this to a person has to be able to name
     * the file, and say what it holds, without parsing prose out of it.
     */
    case WrongSchema(path: String, reason: String, 
        /**
         * Writes still waiting to be sent, which only the build that made
         * the store can send; `None` where its queue cannot be read.
         */unsent: UInt64?, message: String
    )
    case ReadingHandle(message: String
    )
    /**
     * A store SQLite cannot read, or one whose set-aside stopped part way:
     * `setAsideDamaged` keeps it and carries the writes it can read.
     */
    case StoreDamaged(
        /**
         * Empty where the damage was met part way through a call, which
         * does not know the store's path: `checkStore` names it.
         */path: String, reason: String, 
        /**
         * Writes in its queue the server has not taken; `None` where the
         * queue cannot be read whole.
         */unsent: UInt64?, 
        /**
         * True while set-aside recovery blocks removal or replacement.
         */setAsideStopped: Bool, message: String
    )
    /**
     * A removal of a store was refused, leaving it as it was, because the
     * writes it holds that the server has not taken are not those its
     * confirmation was given with. An app reads them again with
     * `readUnsent`, shows them to the person and asks again.
     */
    case UnsentDiffers(path: String, 
        /**
         * How many such writes the store holds; `None` where they cannot be
         * read.
         */unsent: UInt64?, message: String
    )
    /**
     * The copy can no longer be kept current from its cursor: a hydration
     * is owed, and the queue survives it.
     */
    case CopyExpired(reason: String, message: String, 
        /**
         * What a server sent, where its answer ended the copy.
         */server: ServerAnswer?
    )
    case StreamIncomplete(reason: String, message: String, server: ServerAnswer?
    )
    case WrongServer(expected: String, got: String, message: String
    )
    /**
     * The item is whole and its bytes are not here, nor can they be fetched.
     */
    case BytesAbsent(hash: String, reason: String, message: String
    )
    /**
     * The volume holding the file cache has less room than a fetch still has
     * to receive.
     */
    case NoRoom(hash: String, size: UInt64, free: UInt64, message: String
    )
    /**
     * The server speaks a contract this build was not made for, and its
     * answer was not read.
     */
    case ContractMismatch(
        /**
         * The contract the answer named, or none where a success named none.
         */served: String?, expected: UInt64, status: UInt16?, 
        /**
         * The answer was to a write, which may have taken effect.
         */writeSent: Bool, message: String, 
        /**
         * The answer's status, where it was read; its body was not.
         */server: ServerAnswer?
    )
    /**
     * The server's root names a release older than this build supports.
     */
    case ServerTooOld(
        /**
         * The release the server's root names.
         */served: String, 
        /**
         * The oldest release this build works with.
         */oldest: String, message: String
    )
    /**
     * The `Stop` the call was given was raised before it finished.
     */
    case Canceled(message: String
    )
    /**
     * A folder's first sync waits for confirmation, so the call that would
     * write or send for it was refused.
     */
    case FirstSyncWaiting(message: String
    )
    /**
     * A directory's sync is paused, so the call that would read the server's
     * side or write either side was refused until `Folders.resume`.
     */
    case SyncPaused(message: String
    )
    /**
     * The app's `CredentialRenewer` threw `Refused`: the renewal failed for
     * `reason` and the sign-in still stands, which is neither the app's own
     * bad arguments nor a network failure. Queued writes stay queued and the
     * next refusal asks the renewer again. `message` is the renewer's own
     * text, for logs.
     */
    case RenewalRefused(reason: RenewalFailure, message: String
    )
    case Invalid(message: String
    )
    /**
