/**
 * What the server made of a write: one of six, and absent while the write
 * is unanswered.
 */

public enum Verdict: Equatable, Hashable {
    
    case accepted
    /**
     * The server applied the write over changes made since, field by field.
     */
    case merged(fields: [String]
    )
    /**
     * Only item conflicts have a sibling; row conflicts name the replaced cells.
     */
    case conflicted(siblingId: String?, fields: [String], conflicts: [RowConflict]
    )
    /**
     * The refusal read into its parts.
     */
    case refused(refusal: Refusal
    )
    /**
     * Stopped until something outside the queue changes. A write held
     * behind another that has no answer yet is not blocked: it has no
     * verdict, and its `waiting` says so.
     */
    case blocked(reason: BlockedReason, refusal: Refusal?
    )
    /**
     * Refused until the ceiling; released by id. The row's `answer` holds
     * the last answer it got.
     */
    case dead





}

#if compiler(>=6)
extension Verdict: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVerdict: FfiConverterRustBuffer {
    typealias SwiftType = Verdict

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Verdict {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .accepted
        
        case 2: return .merged(fields: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 3: return .conflicted(siblingId: try FfiConverterOptionString.read(from: &buf), fields: try FfiConverterSequenceString.read(from: &buf), conflicts: try FfiConverterSequenceTypeRowConflict.read(from: &buf)
        )
        
        case 4: return .refused(refusal: try FfiConverterTypeRefusal.read(from: &buf)
        )
        
        case 5: return .blocked(reason: try FfiConverterTypeBlockedReason.read(from: &buf), refusal: try FfiConverterOptionTypeRefusal.read(from: &buf)
        )
        
        case 6: return .dead
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Verdict, into buf: inout [UInt8]) {
        switch value {
        
        
        case .accepted:
            writeInt(&buf, Int32(1))
        
        
        case let .merged(fields):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceString.write(fields, into: &buf)
            
        
        case let .conflicted(siblingId,fields,conflicts):
            writeInt(&buf, Int32(3))
            FfiConverterOptionString.write(siblingId, into: &buf)
            FfiConverterSequenceString.write(fields, into: &buf)
            FfiConverterSequenceTypeRowConflict.write(conflicts, into: &buf)
            
        
        case let .refused(refusal):
            writeInt(&buf, Int32(4))
            FfiConverterTypeRefusal.write(refusal, into: &buf)
            
        
        case let .blocked(reason,refusal):
            writeInt(&buf, Int32(5))
            FfiConverterTypeBlockedReason.write(reason, into: &buf)
            FfiConverterOptionTypeRefusal.write(refusal, into: &buf)
            
        
        case .dead:
            writeInt(&buf, Int32(6))
        
        }
    }
}


